}
", "tokenizer.js": "function tokenize(text) {
  const normalized = normalize(text);
  const tokens = [];
  const re = /[A-Za-z0-9]+(?:'[A-Za-z0-9]+)*/g;
  let match;
  while ((match = re.exec(normalized)) !== null) {
    tokens.push(match[0]);
  }
  return tokens;
}
", "pipeline.js": "function processText(text) {
  var tokens = tokenize(text);
  var frequencies = Object.create(null);
  var unique = [];
  var i;
  for (i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    if (frequencies[token] === undefined) {
      frequencies[token] = 0;
      unique.push(token);
    }
    frequencies[token] += 1;
  }
  return {
    text: tokens.join(' '),
    tokens: tokens,
    count: tokens.length,
    unique: unique,
    frequencies: frequencies
  };
}
